sys_relationship.query_with:
(function refineQuery(current, parent) {
    // 1. Get Approval IDs tied to this request
    var appIds = [];
    var app = new GlideRecord('sysapproval_approver');
    app.addQuery('sysapproval', parent.sys_id);
    app.query();
    while (app.next()) {
        appIds.push(app.getUniqueValue());
    }

    // 2. Query sys_email for the parent record OR its approvals
    var qc = current.addQuery('instance', parent.sys_id);
    if (appIds.length > 0) {
        qc.addOrCondition('instance', 'IN', appIds.join(','));
    }
})(current, parent);
